for rxn in HRXN:
    GEOS['%s-%s-monoA-unCP' % (dbse, rxn)] = GEOS['%s-%s-dimer' % (dbse, rxn)].extract_fragments(1)
    GEOS['%s-%s-monoB-unCP' % (dbse, rxn)] = GEOS['%s-%s-dimer' % (dbse, rxn)].extract_fragments(2)
    GEOS['%s-%s-monoA-CP'   % (dbse, rxn)] = GEOS['%s-%s-dimer' % (dbse, rxn)].extract_fragments(1, 2)
    GEOS['%s-%s-monoB-CP'   % (dbse, rxn)] = GEOS['%s-%s-dimer' % (dbse, rxn)].extract_fragments(2, 1)

# <<< Self-Defined Subsets >>>
aaclasses = {
    'posc': ['ARG', 'HIE', 'LYS'],
    'negc': ['ASP', 'GLU'],
    'polr': ['SER', 'THR', 'ASN', 'GLN'],
    'misc': ['CYS', 'GLY', 'MET'],
    'alif': ['PRO', 'ALA', 'VAL', 'ILE', 'LEU'],
    'aryl': ['PHE', 'TYR', 'TRP']
    }
bfdbpattern = re.compile(r"\d\d\d([A-Z][A-Z][A-Z])-\d\d\d([A-Z][A-Z][A-Z])-\d")

PosPos = []
PosNeg = []
PosPolar = []
PosAliph = []
PosAryl = []
NegNeg = []
NegPolar = []
NegAliph = []
NegAryl = []
PolarPolar = []
PolarAliph = []
PolarAryl = []
AliphAliph = []
AliphAryl = []
ArylAryl = []

for rxn in HRXN:
    bfdbname = bfdbpattern.match(rxn)
    aa1 = bfdbname.group(1)
    aa2 = bfdbname.group(2)
    if aa1 in aaclasses['posc'] and aa2 in aaclasses['posc']:
        PosPos.append(rxn)
    if (aa1 in aaclasses['posc'] and aa2 in aaclasses['negc']) or \
       (aa2 in aaclasses['posc'] and aa1 in aaclasses['negc']):
        PosNeg.append(rxn)
    if (aa1 in aaclasses['posc'] and aa2 in aaclasses['polr']) or \
       (aa2 in aaclasses['posc'] and aa1 in aaclasses['polr']):
        PosPolar.append(rxn)
    if (aa1 in aaclasses['posc'] and aa2 in aaclasses['alif']) or  \
       (aa2 in aaclasses['posc'] and aa1 in aaclasses['alif']):
        PosAliph.append(rxn)
    if (aa1 in aaclasses['posc'] and aa2 in aaclasses['aryl']) or  \
       (aa2 in aaclasses['posc'] and aa1 in aaclasses['aryl']):
        PosAryl.append(rxn)
    if aa1 in aaclasses['negc'] and aa2 in aaclasses['negc']:
        NegNeg.append(rxn)
    if (aa1 in aaclasses['negc'] and aa2 in aaclasses['polr']) or \
       (aa2 in aaclasses['negc'] and aa1 in aaclasses['polr']):
        NegPolar.append(rxn)
    if (aa1 in aaclasses['negc'] and aa2 in aaclasses['alif']) or \
       (aa2 in aaclasses['negc'] and aa1 in aaclasses['alif']):
        NegAliph.append(rxn)
    if (aa1 in aaclasses['negc'] and aa2 in aaclasses['aryl']) or \
       (aa2 in aaclasses['negc'] and aa1 in aaclasses['aryl']):
        NegAryl.append(rxn)
    if aa1 in aaclasses['polr'] and aa2 in aaclasses['polr']:
        PolarPolar.append(rxn)
    if (aa1 in aaclasses['polr'] and aa2 in aaclasses['alif']) or \
       (aa2 in aaclasses['polr'] and aa1 in aaclasses['alif']):
        PolarAliph.append(rxn)
    if (aa1 in aaclasses['polr'] and aa2 in aaclasses['aryl']) or \
       (aa2 in aaclasses['polr'] and aa1 in aaclasses['aryl']):
        PolarAryl.append(rxn)
    if aa1 in aaclasses['alif'] and aa2 in aaclasses['alif']:
        AliphAliph.append(rxn)
    if (aa1 in aaclasses['alif'] and aa2 in aaclasses['aryl']) or \
       (aa2 in aaclasses['alif'] and aa1 in aaclasses['aryl']):
        AliphAryl.append(rxn)
    if aa1 in aaclasses['aryl'] and aa2 in aaclasses['aryl']:
        ArylAryl.append(rxn)

